def party_demo(base):
    clues = [dict(q, kind='open', options=[], image_id='') for q in base]
    for t, rows in enumerate(EXTRA,5):
        for i, (question, answer, aliases, explanation) in enumerate(rows):
            clues.append(dict(topic_index=t,price=(i+1)*100,question=question,answer=answer,aliases=aliases,
                              explanation=explanation,kind='open',options=[],image_id=''))
    plan = format_plan(PARTY_TOPICS)
    for q, slot in zip(clues,plan):
        q.update(kind=slot['kind'],image_id=slot['image_id'])
        if q['kind']=='image':
            question,answer,aliases,explanation=IMAGE_CLUES[q['image_id']]
            if q['image_id']=='japan' and q['topic_index']==2:
                question,answer,aliases,explanation=('Какое небесное тело символизирует центральная фигура на этом флаге?','Солнце',['солнце'],'Красный диск символизирует Солнце; японское название флага связано с солнечным кругом.')
            if q['image_id']=='frames' and q['topic_index']==0:
                question,answer,aliases,explanation=('Какая структура Python подходит для хранения этих трёх кадров в порядке воспроизведения?','Список',['list'],'Список сохраняет порядок элементов и допускает обращение по индексу.')
            q.update(question=question,answer=answer,aliases=aliases,explanation=explanation)
        elif q['kind'] in {'audio','video'}:
            question,answer,aliases,explanation=MEDIA_CLUES[q['image_id']]
            q.update(question=question,answer=answer,aliases=aliases,explanation=explanation)
        elif q['kind']=='riddle':
            question,answer,aliases,explanation=RIDDLES[q['topic_index']]
            q.update(question=question,answer=answer,aliases=aliases,explanation=explanation)
    for q in clues:
        if q['kind']=='choice':
            seen={q['answer'].strip().casefold()}
            alternatives=[]
            for r in clues:
                if r['topic_index']==q['topic_index'] and r['answer'].strip().casefold() not in seen:
                    alternatives.append(r['answer'])
                    seen.add(r['answer'].strip().casefold())
            q['options']=random.sample([q['answer'],*alternatives[:3]],4)
    return clues
